const body = $json.body || {};
const env = (name) => (typeof $env === 'function' ? $env(name) : undefined);

const sheetId = body.sheet_id || body.sheetId;
if (!sheetId) {
  throw new Error('sheet_id es requerido.');
}

const sheetName = (body.sheet_name || body.sheetName || 'Copys').toString();
let range = (body.range || `${sheetName}!A:O`).toString();
if (!range.includes('!')) {
  range = `${sheetName}!${range}`;
}

const limit = Math.max(1, Math.min(10, Number(body.limit) || 3));
const headerRow = Math.max(1, Number(body.header_row || body.headerRow || 1) || 1);

const statusField = (body.status_field || body.statusField || 'status').toString();
const urlField = (body.url_field || body.urlField || 'url').toString();
const linkedinField = (body.linkedin_field || body.linkedinField || 'linkedin_copy').toString();
const facebookField = (body.facebook_field || body.facebookField || 'facebook_copy').toString();
const platformsField = (body.platforms_field || body.platformsField || 'platforms').toString();
const toneField = (body.tone_field || body.toneField || 'tone').toString();
const targetField = (body.target_audience_field || body.targetAudienceField || 'target_audience').toString();
const ctaField = (body.call_to_action_field || body.callToActionField || 'call_to_action').toString();
const notesField = (body.notes_field || body.notesField || 'notes').toString();
const lastGeneratedField = (body.last_generated_field || body.lastGeneratedField || 'last_generated_at').toString();

const rapidApiKey = (body.rapidapi_key || body.rapidApiKey || env('RAPIDAPI_YOUTUBE_KEY') || '').toString().trim();
const openAiModel = (body.openai_model || env('OPENAI_SOCIAL_MODEL') || env('OPENAI_DEFAULT_MODEL') || 'gpt-4o').toString();

return [{
  json: {
    sheet_id: sheetId,
    sheet_name: sheetName,
    range,
    limit,
    header_row: headerRow,
    status_field: statusField,
    url_field: urlField,
    linkedin_field: linkedinField,
    facebook_field: facebookField,
    platforms_field: platformsField,
    tone_field: toneField,
    target_field: targetField,
    cta_field: ctaField,
    notes_field: notesField,
    last_generated_field: lastGeneratedField,
    rapidapi_key: rapidApiKey || null,
    openai_model: openAiModel,
    default_generated_status: (body.generated_status || 'generated').toString(),
    default_processing_status: (body.processing_status || 'processing').toString()
  }
}];

function normalizeKey(value, index) {
  const raw = (value ?? '').toString().trim();
  if (!raw) return `col_${index + 1}`;
  return raw
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+/, '')
    .replace(/_+$/, '')
    || `col_${index + 1}`;
}

const config = $items('Validar Entrada Sheets', 0)[0]?.json || {};
const values = $json.values || $json.data || [];
if (!Array.isArray(values) || !values.length) {
  return [];
}

const headersRaw = values[0].map((value) => (value ?? '').toString().trim());
const headerKeys = headersRaw.map(normalizeKey);
const columnMap = {};
headerKeys.forEach((key, idx) => {
  columnMap[key] = idx;
});

const allowedStatuses = new Set(['pending', 'pendiente', 'to_do', 'todo', '']);
const limit = config.limit || 3;
const statusKey = normalizeKey(config.status_field || 'status', 0);
const urlKey = normalizeKey(config.url_field || 'url', 1);

const rows = [];
for (let i = 1; i < values.length; i++) {
  const rowValues = Array.isArray(values[i]) ? values[i] : [];
  const data = {};
  headerKeys.forEach((key, idx) => {
    data[key] = (rowValues[idx] ?? '').toString();
  });

  const statusValue = (data[statusKey] || '').toString().trim().toLowerCase();
  const urlValue = (data[urlKey] || '').toString().trim();
  if (!urlValue) continue;
  if (!allowedStatuses.has(statusValue) && statusValue !== config.default_processing_status) continue;

  const rowIndex = config.header_row + i;
  rows.push({
    sheet_id: config.sheet_id,
    sheet_name: config.sheet_name,
    range: config.range,
    row_number: rowIndex,
    headers_raw: headersRaw,
    header_keys: headerKeys,
    column_map: columnMap,
    row_values: rowValues,
    row_data: data,
    status_value: statusValue,
    request_config: config,
    row_index_in_range: i
  });

  if (rows.length >= limit) break;
}

return rows.map((row) => ({ json: row }));

                    function normalizeKey(label, fallback) {
                      const base = (label || fallback || '').toString().trim();
                      if (!base) return fallback;
                      const normalized = base
                        .toLowerCase()
                        .replace(/[^a-z0-9]+/g, '_')
                        .replace(/^_+/, '')
                        .replace(/_+$/, '');
                      return normalized || fallback;
                    }

                    function toArray(value) {
                      if (value === undefined || value === null) return [];
                      if (Array.isArray(value)) return value.map((v) => (v ?? '').toString().trim()).filter(Boolean);
                      if (typeof value === 'string') {
                        return value
                          .split(/,|
|;|\|/)
                          .map((part) => part.trim())
                          .filter(Boolean);
                      }
                      return [];
                    }

                    const row = $json || {};
                    const config = row.request_config || {};
                    const data = row.row_data || {};

                    const platformsKey = normalizeKey(config.platforms_field, 'platforms');
                    const platforms = toArray(data[platformsKey] || data.platforms)
                      .map((value) => value.toLowerCase());
                    const uniquePlatforms = Array.from(new Set(platforms.filter((value) => ['linkedin', 'facebook'].includes(value))));
                    const resolvedPlatforms = uniquePlatforms.length ? uniquePlatforms : ['linkedin', 'facebook'];

                    const urlKey = normalizeKey(config.url_field, 'url');
                    const urlValue = (data[urlKey] || data.url || '').toString().trim();
                    if (!urlValue) {
                      throw new Error('La fila no contiene URL.');
                    }

                    const sourceType = /youtube\.com|youtu\.be/i.test(urlValue) ? 'youtube' : 'article';
                    if (sourceType === 'youtube' && !config.rapidapi_key) {
                      throw new Error('Se requiere rapidapi_key para procesar enlaces de YouTube.');
                    }

                    const toneKey = normalizeKey(config.tone_field, 'tone');
                    const targetKey = normalizeKey(config.target_field, 'target_audience');
                    const ctaKey = normalizeKey(config.cta_field, 'call_to_action');
                    const notesKey = normalizeKey(config.notes_field, 'notes');

                    const tone = (data[toneKey] || 'profesional cercano').toString();
                    const targetAudience = (data[targetKey] || 'Profesionales en marketing y growth').toString();
                    const callToAction = (data[ctaKey] || 'Invita a comentar y compartir.').toString();
                    const notes = (data[notesKey] || '').toString();

                    const title = (data.title || data.topic || data.headline || '').toString();

                    return [{
                      json: {
                        ...row,
                        source_url: urlValue,
                        source_type: sourceType,
                        platforms: resolvedPlatforms,
                        tone,
                        target_audience: targetAudience,
                        call_to_action: callToAction,
                        extra_notes: notes,
                        selected_title: title || null,
                        rapidapi_key: config.rapidapi_key || null,
                        openai_model: config.openai_model || 'gpt-4o'
                      }
                    }];

const ctx = $items('Preparar Contexto Sheets', 0)[$itemIndex]?.json || {};
const payload = $json || {};
let transcript = '';

if (Array.isArray(payload.transcript)) {
  transcript = payload.transcript.map((item) => (item.text || item || '').toString().trim()).join(' ');
} else if (Array.isArray(payload.data)) {
  transcript = payload.data.map((item) => (item.text || item || '').toString().trim()).join(' ');
} else if (typeof payload.text === 'string') {
  transcript = payload.text;
} else if (payload.results && Array.isArray(payload.results)) {
  transcript = payload.results.map((item) => (item.text || '').toString().trim()).join(' ');
}

if (!transcript) {
  throw new Error('La API de transcripción no devolvió texto utilizable.');
}

return [{
  json: {
    ...ctx,
    content_text: transcript.replace(/\s+/g, ' ').trim()
  }
}];

const ctx = $items('Preparar Contexto Sheets', 0)[$itemIndex]?.json || {};
const html = ($json || '').toString();
if (!html) {
  throw new Error('No se recibió HTML del artículo.');
}

const withoutScripts = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ');
const text = withoutScripts
  .replace(/<[^>]+>/g, ' ')
  .replace(/&(nbsp|amp|quot|lt|gt);/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{
  json: {
    ...ctx,
    content_text: text
  }
}];

                    function truncate(text, max) {
                      if (!text) return '';
                      if (text.length <= max) return text;
                      return text.slice(0, max - 3).trim() + '...';
                    }

                    const data = $json || {};
                    const plain = (data.content_text || '').toString().replace(/\s+/g, ' ').trim();
                    if (!plain) {
                      throw new Error('No se pudo obtener contenido base para generar copys.');
                    }

                    const excerpt = truncate(plain, 6000);
                    const summary = truncate(plain, 600);

                    const articlePayload = {
                      sheet_id: data.sheet_id,
                      sheet_name: data.sheet_name,
                      row_number: data.row_number,
                      url: data.source_url,
                      source_type: data.source_type,
                      title: data.selected_title || '',
                      tone: data.tone,
                      target_audience: data.target_audience,
                      call_to_action: data.call_to_action,
                      platforms: data.platforms,
                      notes: data.extra_notes,
                      summary,
                      excerpt
                    };

                    const formatDescription = `Devuelve un JSON válido (sin bloques markdown) con las claves únicamente para las plataformas solicitadas (${data.platforms.join(', ')}). Cada plataforma debe seguir la estructura:
{
  "hook": "Frase inicial potente (máx. 2 frases)",
  "body": "Desarrollo de hasta 3 párrafos cortos",
  "cta": "Llamado a la acción coherente",
  "hashtags": ["#Ejemplo"],
  "emojis": ["🙂"],
  "suggested_asset": "Idea de recurso gráfico opcional",
  "angle": "Resumen del ángulo creativo"
}`;

                    const constraints = [`Mantén un tono ${data.tone}.`,
                      'Responde en español neutro.',
                      'Incluye la keyword o concepto principal del título/URL al menos una vez.',
                      'Limita LinkedIn a 1300 caracteres y Facebook a 2000.',
                      'Integra hashtags relevantes (máx. 5).',
                      'Aprovecha notas extra si existen para reforzar el ángulo narrativo.',
                      'Evita repetir literalmente frases largas del artículo.'
                    ];

                    const prompt = [`Resumen del contexto (JSON):`, JSON.stringify(articlePayload, null, 2), '', formatDescription, '', 'Restricciones:', ...constraints, '', 'Entrega sólo el JSON solicitado.'].join('
');

                    return [{
                      json: {
                        ...data,
                        article_plain: plain,
                        article_summary: summary,
                        article_excerpt: excerpt,
                        prompt
                      }
                    }];

                    function normalizeKey(label, fallback) {
                      const base = (label || fallback || '').toString().trim();
                      if (!base) return fallback;
                      const normalized = base
                        .toLowerCase()
                        .replace(/[^a-z0-9]+/g, '_')
                        .replace(/^_+/, '')
                        .replace(/_+$/, '');
                      return normalized || fallback;
                    }

                    const rawMessage = $json.message?.content || $json.text || $json.response || '';
                    let cleaned = String(rawMessage).trim();
                    if (cleaned.startsWith('```json')) {
                      cleaned = cleaned.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
                    } else if (cleaned.startsWith('```')) {
                      cleaned = cleaned.replace(/^```\s*/i, '').replace(/```$/i, '').trim();
                    }

                    let parsed;
                    try {
                      parsed = JSON.parse(cleaned);
                    } catch (error) {
                      throw new Error('No se pudo parsear la respuesta del modelo a JSON. Respuesta:
' + cleaned);
                    }

                    const context = $items('Preparar Prompt Sheets', 0)[$itemIndex]?.json || {};
                    const platforms = context.platforms || ['linkedin', 'facebook'];

                    function resolvePlatform(data, key) {
                      if (!data) return null;
                      const direct = data[key];
                      if (direct) return direct;
                      const alt = data[key.charAt(0).toUpperCase() + key.slice(1)];
                      if (alt) return alt;
                      if (key === 'linkedin') {
                        return data.LinkedIn || data.linked_in || data.linkedin_post || null;
                      }
                      if (key === 'facebook') {
                        return data.Facebook || data.facebook_post || null;
                      }
                      return null;
                    }

                    function buildCopy(block, fallback) {
                      if (!block || typeof block !== 'object') {
                        return fallback || null;
                      }
                      const parts = [];
                      if (block.hook) parts.push(block.hook.trim());
                      if (block.body) parts.push(block.body.trim());
                      if (block.cta) parts.push(block.cta.trim());
                      if (Array.isArray(block.hashtags) && block.hashtags.length) {
                        const tags = block.hashtags.map((tag) => (tag || '').toString().trim()).filter(Boolean);
                        if (tags.length) parts.push(tags.join(' '));
                      }
                      return parts.filter(Boolean).join('

') || fallback || null;
                    }

                    const linkedinStruct = resolvePlatform(parsed, 'linkedin');
                    const facebookStruct = resolvePlatform(parsed, 'facebook');

                    const linkedinCopy = platforms.includes('linkedin') ? buildCopy(linkedinStruct, null) : null;
                    const facebookCopy = platforms.includes('facebook') ? buildCopy(facebookStruct, null) : null;

                    const usage = $json.usage || $json.data?.[0]?.usage || {};
                    const totalTokens = usage.total_tokens ?? usage.totalTokens ?? null;

                    const rowValues = Array.from(context.row_values || []);
                    const headers = context.header_keys || [];
                    const config = context.request_config || {};
                    const statusKey = normalizeKey(config.status_field, 'status');
                    const linkedinKey = normalizeKey(config.linkedin_field, 'linkedin_copy');
                    const facebookKey = normalizeKey(config.facebook_field, 'facebook_copy');
                    const lastGeneratedKey = normalizeKey(config.last_generated_field, 'last_generated_at');

                    const nowIso = new Date().toISOString();

                    headers.forEach((key, idx) => {
                      if (key === statusKey) {
                        rowValues[idx] = config.default_generated_status || 'generated';
                      } else if (key === linkedinKey) {
                        rowValues[idx] = linkedinCopy || rowValues[idx] || '';
                      } else if (key === facebookKey) {
                        rowValues[idx] = facebookCopy || rowValues[idx] || '';
                      } else if (key === lastGeneratedKey) {
                        rowValues[idx] = nowIso;
                      } else if (rowValues[idx] === undefined || rowValues[idx] === null) {
                        rowValues[idx] = '';
                      }
                    });

                    function columnLetter(len) {
                      let n = len;
                      let letters = '';
                      while (n > 0) {
                        const mod = (n - 1) % 26;
                        letters = String.fromCharCode(65 + mod) + letters;
                        n = Math.floor((n - mod) / 26);
                      }
                      return letters;
                    }

                    const endColumnLetter = columnLetter(headers.length || 1);
                    const rangeToUpdate = `${context.sheet_name}!A${context.row_number}:${endColumnLetter}${context.row_number}`;

                    return [{
                      json: {
                        ...context,
                        structured_copies: parsed,
                        linkedin_copy_new: linkedinCopy,
                        facebook_copy_new: facebookCopy,
                        llm_tokens_used: totalTokens,
                        row_values: rowValues,
                        range_to_update: rangeToUpdate,
                        generated_at_iso: nowIso
                      }
                    }];

const context = $items('Parsear Copys Sheets', 0)[$itemIndex]?.json || {};
const endTime = new Date();
const durationMs = Math.max(0, Date.now() - (context.start_ts_ms || Date.now()));

const jobLog = {
  job_name: 'SEO - 16 Copys Redes Sheets',
  job_type: 'social_copy',
  status: 'success',
  related_keyword_id: null,
  related_idea_id: null,
  related_draft_id: null,
  started_at: context.start_time || endTime.toISOString(),
  completed_at: endTime.toISOString(),
  duration_ms: durationMs,
  input_data: {
    sheet_id: context.sheet_id,
    sheet_name: context.sheet_name,
    row_number: context.row_number,
    url: context.source_url,
    platforms: context.platforms,
    tone: context.tone
  },
  output_data: {
    linkedin_copy: context.linkedin_copy_new,
    facebook_copy: context.facebook_copy_new,
    structured_copies: context.structured_copies,
    tokens_used: context.llm_tokens_used,
    range: context.range_to_update
  }
};

return [{ json: { ...context, job_log: jobLog } }];

parameters.query:
=INSERT INTO jobs_log (job_name, job_type, status, related_keyword_id, related_idea_id, related_draft_id, started_at, completed_at, duration_ms, input_data, output_data)
VALUES ($1, $2, $3, $4, $5, $6, $7::timestamp, $8::timestamp, $9, $10::jsonb, $11::jsonb)
RETURNING id, job_name, status, created_at;

parameters.jsCode:
const context = $items('Preparar Job Log Sheets', 0)[$itemIndex]?.json || {};
const row = $json || {};
return [{
  json: {
    ...context,
    job_log_id: row.id || null,
    job_log_created_at: row.created_at || null
  }
}];

const items = $json.processed_items || [];
return [{
  json: {
    status: items.length ? 'success' : 'empty',
    total: items.length,
    rows: items.map((item) => ({
      sheet_id: item.sheet_id,
      sheet_name: item.sheet_name,
      row_number: item.row_number,
      url: item.source_url,
      platforms: item.platforms,
      linkedin_copy: item.linkedin_copy_new,
      facebook_copy: item.facebook_copy_new,
      job_log_id: item.job_log_id
    })),
    generated_at: new Date().toISOString()
  }
}];
